namespace Csl.Engine;

/// <summary>
/// Film-grain shader.
/// Adapted from the shader of Martins Upitis.
/// http://devlog-martinsh.blogspot.ca/2013/05/image-imperfections-and-film-grain-post.html
/// </summary>
[Shader(External = true, Internal = true)]
