    // Amount
    public float Amount;

    // Time changing at each frame for the animation
    public float Time;

    // Size of the grain
    public float GrainSize;

    // How the luminance influences the amount of grain.
    public float LuminanceFactor;

    public override float4 Compute(float4 color)
    {
        float2 texCoord = streams.TexCoord;

        float2 rotCoordsR = coordRot(texCoord, Time);
        float2 newCoord = rotCoordsR / Texture0TexelSize / GrainSize;
        float n = pnoise3D(new float3(newCoord, 0.0f));
        float3 noiseFactor = new float3(n, n, n);

        float3 col = color.rgb;

        // Noisiness response curve based on scene luminance
        float luminance = lerp(0.0f, LuminanceUtils.Luma(col), LuminanceFactor);
        float lum = smoothstep(0.2f, 0.0f, luminance) + luminance;

        noiseFactor = saturate(lerp(noiseFactor, new float3(0.0f, 0.0f, 0.0f), pow(lum, 4.0f)));
        color.rgb += noiseFactor * Amount;

        return color;
    }


    // Random texture generation
    public virtual float4 rnm(float2 tc)
    {
        float noiseFactor = sin(dot(tc + new float2(Time, Time), new float2(12.9898f, 78.233f))) * 43758.5453f;

        float4 result = new float4(frac(noiseFactor), frac(noiseFactor * 1.2154f), frac(noiseFactor * 1.3453f), frac(noiseFactor * 1.3647f));
        return result * 2.0f - 1;
    }

    public virtual float fade(float t)
    {
        return Sdsl.Static<Math>().Quintic(t);
    }

    public virtual float pnoise3D(float3 p)
    {
        float permTexUnit = 1.0f / 256.0f;
        float permTexUnitHalf = permTexUnit * 0.5f;

        float3 pi = permTexUnit * floor(p) + permTexUnitHalf;
        // Integer part, scaled so +1 moves permTexUnit texel
        // and offset 1/2 texel to sample texel centers
        float3 pf = frac(p);
        // Fractional part for interpolation

        // Noise contributions from (x=0, y=0), z=0 and z=1
        float perm00 = rnm(pi.xy).a;
        float3 grad000 = rnm(new float2(perm00, pi.z)).rgb * 4.0f - 1.0f;
        float n000 = dot(grad000, pf);
        float3 grad001 = rnm(new float2(perm00, pi.z + permTexUnit)).rgb * 4.0f - 1.0f;
        float n001 = dot(grad001, pf - new float3(0.0f, 0.0f, 1.0f));

        // Noise contributions from (x=0, y=1), z=0 and z=1
        float perm01 = rnm(pi.xy + new float2(0.0f, permTexUnit)).a;
        float3 grad010 = rnm(new float2(perm01, pi.z)).rgb * 4.0f - 1.0f;
        float n010 = dot(grad010, pf - new float3(0.0f, 1.0f, 0.0f));
        float3 grad011 = rnm(new float2(perm01, pi.z + permTexUnit)).rgb * 4.0f - 1.0f;
        float n011 = dot(grad011, pf - new float3(0.0f, 1.0f, 1.0f));

        // Noise contributions from (x=1, y=0), z=0 and z=1
        float perm10 = rnm(pi.xy + new float2(permTexUnit, 0.0f)).a;
        float3 grad100 = rnm(new float2(perm10, pi.z)).rgb * 4.0f - 1.0f;
        float n100 = dot(grad100, pf - new float3(1.0f, 0.0f, 0.0f));
        float3 grad101 = rnm(new float2(perm10, pi.z + permTexUnit)).rgb * 4.0f - 1.0f;
        float n101 = dot(grad101, pf - new float3(1.0f, 0.0f, 1.0f));

        // Noise contributions from (x=1, y=1), z=0 and z=1
        float perm11 = rnm(pi.xy + new float2(permTexUnit, permTexUnit)).a;
        float3 grad110 = rnm(new float2(perm11, pi.z)).rgb * 4.0f - 1.0f;
        float n110 = dot(grad110, pf - new float3(1.0f, 1.0f, 0.0f));
        float3 grad111 = rnm(new float2(perm11, pi.z + permTexUnit)).rgb * 4.0f - 1.0f;
        float n111 = dot(grad111, pf - new float3(1.0f, 1.0f, 1.0f));

        // Blend contributions along x
        float4 n_x = lerp(new float4(n000, n001, n010, n011), new float4(n100, n101, n110, n111), fade(pf.x));

        // Blend contributions along y
        float2 n_xy = lerp(n_x.xy, n_x.zw, fade(pf.y));

        // Blend contributions along z
        float n_xyz = lerp(n_xy.x, n_xy.y, fade(pf.z));

        // We're done, return the final noise value.
        return n_xyz;
    }

    public virtual float2 coordRot(float2 tc, float angle)
    {
        float aspect = Texture0TexelSize.y / Texture0TexelSize.x;
        float rotX = ((tc.x * 2.0f - 1.0f) * aspect * cos(angle)) - ((tc.y * 2.0f - 1.0f) * sin(angle));
        float rotY = ((tc.y * 2.0f - 1.0f) * cos(angle)) + ((tc.x * 2.0f - 1.0f) * aspect * sin(angle));
        rotX = ((rotX / aspect) * 0.5f + 0.5f);
        rotY = rotY * 0.5f + 0.5f;
        return new float2(rotX, rotY);
    }
}
